import { useEffect, useMemo, useRef, useState } from "react";
import { ArrowRight, Check, CircleDot, Copy, ExternalLink, FileCheck2, Loader2, LockKeyhole, RefreshCw, RotateCcw, ShieldCheck, Sparkles, WalletCards, X } from "lucide-react";
import { trpc } from "@/lib/trpc";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { isLiveTxHash, PROOFLOAN_STATES, type SourceChain } from "@shared/proofloan";
import { getMobileErrorNoticeModel } from "@/lib/mobileErrorNotice";
import { clearStoredApplicationId, getSafeSessionStorage, persistApplicationId, readStoredApplicationId } from "@/lib/applicationSession";
import { scheduleFeedbackReset, type FeedbackTimer } from "@/lib/transientFeedback";
import { isDashboardFailureDebugEnabled } from "@/lib/mobileDebug";
import { getAcceptanceFailureRecovery, getMobileActionAvailability, getMobileCreditFileViewState, shouldClearMissingApplication, shouldInvokeMobileAction, shouldPollCreditFile, shouldRetryCreditFileQuery, shouldShowAcceptanceError } from "@/lib/mobileRecoveryState";
import { getAcceptanceIdempotencyRef, type AcceptanceIdempotencyRef } from "@/lib/acceptanceIdempotency";
import { getProofRequestIdempotencyKey } from "@/lib/proofRequestIdempotency";
import { getProofIdentityValidationError } from "@/lib/proofIdentityValidation";
import { appendReplayRefreshTimelineEvent, appendReplayRefreshThresholdAuditEvent, areReplayRefreshSeverityThresholdsEqual, categorizeReplayRefreshFailure, formatReplayDiagnosticsTimestamp, getReplayDiagnosticsFreshness, getReplayDiagnosticsRefreshFeedback, getReplayDiagnosticsRefreshState, filterReplayRefreshTimeline, getReplayDiagnosticsRows, getReplayRefreshCategoryCounts, getReplayRefreshCategoryTrends, getReplayRefreshFailureLabel, getReplayRefreshSeverityExplanation, getReplayRefreshSeverityNotice, getReplayRefreshSeverityPersistenceNotice, getReplayRefreshSeverityPersistenceStatus, getReplayRefreshSeverityPersistenceTransition, persistReplayRefreshSeverityThresholds, shouldApplyReplayRefreshPersistenceUpdate, getReplayRefreshSeverityStatusSummary, getReplayRefreshThresholdAuditAriaLabel, getReplayRefreshThresholdAuditLabel, getReplayRefreshFilterChangeNotice, getReplayRefreshFilterChangeScopeNotice, getReplayRefreshFilterLabel, getReplayRefreshFilterScopeLabel, getReplayRefreshFilterRestorationNotice, getReplayRefreshTimelineSummary, readReplayRefreshSeverityThresholds, readReplayRefreshTimelineFilter, shouldShowReplayRefreshFilterReset, writeReplayRefreshSeverityThresholds, writeReplayRefreshTimelineFilter, getReplayRefreshTrend, normalizeReplayDiagnostics, normalizeReplayRefreshSeverityThresholds, shouldApplyReplayRefreshOutcome, type ReplayDiagnosticsRefreshOutcome, type ReplayRefreshTimelineEvent, type ReplayRefreshThresholdAuditEvent, type ReplayRefreshTimelineFilter } from "@/lib/replayDiagnosticsView";

const demoWallet = "0x71C7...9A2F";

function MobileErrorNotice({ title, error, onRetry }: { title: string; error: { message: string }; onRetry?: () => void }) {
  const notice = getMobileErrorNoticeModel(error.message, Boolean(onRetry));
  return <div role="alert" aria-live="assertive" className="mobile-error-notice rounded-xl border border-rose-300/20 bg-rose-400/10 p-3 text-xs leading-5 text-rose-200"><div className="flex items-start gap-2"><X size={15} className="mt-0.5 shrink-0 text-rose-300" /><div className="min-w-0"><div className="font-semibold">{title} <span className="ml-1 font-mono text-[10px] text-rose-300/70">{notice.code}</span></div><p className="mt-1 break-words">{notice.message}</p><p className="mt-2 text-[11px] leading-5 text-rose-200/70">{notice.guidance}</p>{notice.canRetry && <Button type="button" variant="outline" aria-label={notice.actionLabel} onClick={onRetry} className="mt-3 min-h-10 rounded-lg border-rose-300/25 px-3 text-xs text-rose-100 hover:bg-rose-400/10"><RotateCcw size={13} /> {notice.actionLabel}</Button>}</div></div></div>;
}

export default function Home() {
  const [walletAddress, setWalletAddress] = useState("");
  const [sourceChain, setSourceChain] = useState<SourceChain>("Ethereum Sepolia");
  const [applicationId, setApplicationId] = useState<string | null>(() => typeof window === "undefined" ? null : readStoredApplicationId(getSafeSessionStorage(() => window.sessionStorage)));
  const [copied, setCopied] = useState(false);
  const [proofSubmitted, setProofSubmitted] = useState(false);
  const [offerSubmitted, setOfferSubmitted] = useState(false);
  const [activeSection, setActiveSection] = useState("apply");
  const [activeTab, setActiveTab] = useState("evidence");
  const [debugDashboardFailure, setDebugDashboardFailure] = useState(() => isDashboardFailureDebugEnabled(import.meta.env.DEV, typeof window === "undefined" ? "" : window.location.search));
  const [inputError, setInputError] = useState<string | null>(null);
  const [copyError, setCopyError] = useState<string | null>(null);
  const copyResetTimer = useRef<FeedbackTimer | null>(null);
  const acceptanceIdempotencyRef = useRef<AcceptanceIdempotencyRef | null>(null);
  const proofRequestIdempotencyRef = useRef<ReturnType<typeof getProofRequestIdempotencyKey> | null>(null);
  const [isOnline, setIsOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  const [pollingPaused, setPollingPaused] = useState(false);
  const [replayRefreshOutcome, setReplayRefreshOutcome] = useState<ReplayDiagnosticsRefreshOutcome>("idle");
  const [replayTimelineFilter, setReplayTimelineFilter] = useState<ReplayRefreshTimelineFilter>(() => readReplayRefreshTimelineFilter(typeof window === "undefined" ? undefined : window.sessionStorage));
  const [replayTimelineFilterRestored, setReplayTimelineFilterRestored] = useState(() => typeof window !== "undefined" && readReplayRefreshTimelineFilter(window.sessionStorage) !== "all");
  const [replayTimelineFilterChangeNotice, setReplayTimelineFilterChangeNotice] = useState<string | null>(null);
  const [replayRefreshSeverityThresholds, setReplayRefreshSeverityThresholds] = useState(() => readReplayRefreshSeverityThresholds(typeof window === "undefined" ? undefined : window.sessionStorage));
  const [replayRefreshSeverityNotice, setReplayRefreshSeverityNotice] = useState<string | null>(null);
  const [replayRefreshSeverityPersistenceWarning, setReplayRefreshSeverityPersistenceWarning] = useState<string | null>(null);
  const [replayRefreshSeverityPersistenceStatus, setReplayRefreshSeverityPersistenceStatus] = useState("");
  const [replayRefreshSeverityPersistenceAvailable, setReplayRefreshSeverityPersistenceAvailable] = useState<boolean | null>(null);
  const [replayRefreshTimeline, setReplayRefreshTimeline] = useState<ReplayRefreshTimelineEvent[]>([]);
  const [replayRefreshThresholdAudit, setReplayRefreshThresholdAudit] = useState<ReplayRefreshThresholdAuditEvent[]>([]);
  const replayRefreshRequestRef = useRef(0);
  const replayRefreshMountedRef = useRef(true);
  useEffect(() => () => {
    replayRefreshMountedRef.current = false;
    replayRefreshRequestRef.current += 1;
  }, []);
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);
  useEffect(() => () => {
    if (copyResetTimer.current !== null) clearTimeout(copyResetTimer.current);
  }, []);
  useEffect(() => {
    if (typeof window === "undefined") return;
    const storage = getSafeSessionStorage(() => window.sessionStorage);
    if (applicationId) persistApplicationId(storage, applicationId);
    else clearStoredApplicationId(storage);
  }, [applicationId]);
  const proofloanUtils = trpc.useUtils();
  const authQuery = trpc.auth.me.useQuery();
  const replayDiagnostics = trpc.proofloan.replayDiagnostics.useQuery(undefined, { enabled: authQuery.data?.role === "admin", refetchInterval: 30_000 });
  const safeReplayDiagnostics = normalizeReplayDiagnostics(replayDiagnostics.data);
  const replayDiagnosticsFreshness = safeReplayDiagnostics ? getReplayDiagnosticsFreshness(safeReplayDiagnostics.generatedAt) : "invalid";
  const replayDiagnosticsRefresh = getReplayDiagnosticsRefreshState({ isFetching: replayDiagnostics.isFetching, isOnline });
  const replayRefreshFeedback = getReplayDiagnosticsRefreshFeedback(replayRefreshOutcome);
  const replayRefreshTimelineSummary = getReplayRefreshTimelineSummary(replayRefreshTimeline);
  const replayRefreshTrend = getReplayRefreshTrend(replayRefreshTimeline);
  const replayRefreshCategoryCounts = getReplayRefreshCategoryCounts(replayRefreshTimeline);
  const replayRefreshCategoryTrends = getReplayRefreshCategoryTrends(replayRefreshTimeline, replayRefreshSeverityThresholds);
  const filteredReplayRefreshTimeline = filterReplayRefreshTimeline(replayRefreshTimeline, replayTimelineFilter);
  useEffect(() => { writeReplayRefreshTimelineFilter(typeof window === "undefined" ? undefined : window.sessionStorage, replayTimelineFilter); }, [replayTimelineFilter]);
  useEffect(() => { const result = persistReplayRefreshSeverityThresholds(typeof window === "undefined" ? undefined : window.sessionStorage, replayRefreshSeverityThresholds, replayRefreshSeverityPersistenceAvailable); if (!shouldApplyReplayRefreshPersistenceUpdate({ isMounted: replayRefreshMountedRef.current, persisted: replayRefreshSeverityThresholds, current: replayRefreshSeverityThresholds })) return; setReplayRefreshSeverityPersistenceWarning(previous => previous === result.warning ? previous : result.warning); setReplayRefreshSeverityPersistenceAvailable(previous => previous === result.available ? previous : result.available); setReplayRefreshSeverityPersistenceStatus(previous => previous === result.status ? previous : result.status); }, [replayRefreshSeverityThresholds]);
  useEffect(() => { if (!replayTimelineFilterRestored) return; const timer = window.setTimeout(() => setReplayTimelineFilterRestored(false), 4000); return () => window.clearTimeout(timer); }, [replayTimelineFilterRestored]);
  useEffect(() => { if (!replayRefreshSeverityNotice) return; const timer = window.setTimeout(() => setReplayRefreshSeverityNotice(null), 2500); return () => window.clearTimeout(timer); }, [replayRefreshSeverityNotice]);
  useEffect(() => { if (!replayTimelineFilterChangeNotice) return; const timer = window.setTimeout(() => setReplayTimelineFilterChangeNotice(null), 2500); return () => window.clearTimeout(timer); }, [replayTimelineFilterChangeNotice]);
  const changeReplayTimelineFilter = (next: ReplayRefreshTimelineFilter) => { setReplayTimelineFilterChangeNotice(getReplayRefreshFilterChangeScopeNotice(replayTimelineFilter, next, filterReplayRefreshTimeline(replayRefreshTimeline, next).length) ?? getReplayRefreshFilterChangeNotice(replayTimelineFilter, next)); setReplayTimelineFilter(next); };
  const recordReplayThresholdAudit = (kind: "saved" | "restored", thresholds: { attentionCount: number; criticalCount: number }) => { if (!replayRefreshMountedRef.current) return; setReplayRefreshThresholdAudit(events => appendReplayRefreshThresholdAuditEvent(events, { kind, ...thresholds })); };
  const refreshReplayDiagnostics = () => {
    if (!replayDiagnosticsRefresh.enabled) return;
    const requestId = replayRefreshRequestRef.current + 1;
    replayRefreshRequestRef.current = requestId;
    setReplayRefreshOutcome("refreshing");
    void replayDiagnostics.refetch().then(result => {
      if (!shouldApplyReplayRefreshOutcome({ requestId, currentRequestId: replayRefreshRequestRef.current, isMounted: replayRefreshMountedRef.current })) return;
      const outcome = result.isError ? "error" : "success";
      setReplayRefreshOutcome(outcome);
      setReplayRefreshTimeline(events => appendReplayRefreshTimelineEvent(events, outcome, new Date().toISOString(), Date.now(), result.isError ? categorizeReplayRefreshFailure(result.error) : undefined));
    }).catch(() => {
      if (!shouldApplyReplayRefreshOutcome({ requestId, currentRequestId: replayRefreshRequestRef.current, isMounted: replayRefreshMountedRef.current })) return;
      setReplayRefreshOutcome("error");
      setReplayRefreshTimeline(events => appendReplayRefreshTimelineEvent(events, "error", new Date().toISOString(), Date.now(), categorizeReplayRefreshFailure(undefined)));
    });
  };
  const createApplication = trpc.proofloan.createApplication.useMutation({ onMutate: () => { setProofSubmitted(false); setInputError(null); }, onSuccess: data => { acceptanceIdempotencyRef.current = null; setApplicationId(data.applicationId); setPollingPaused(false); setProofSubmitted(true); } });
  const acceptOffer = trpc.proofloan.acceptOffer.useMutation({ onMutate: () => setOfferSubmitted(false), onSuccess: () => setOfferSubmitted(true), onError: (_error, variables) => { const recovery = getAcceptanceFailureRecovery({ hasApplication: Boolean(variables.applicationId), isOnline, pollingPaused }); if (recovery.shouldInvalidateCreditFile) { if (recovery.shouldResumePolling) setPollingPaused(false); void proofloanUtils.proofloan.getApplication.invalidate({ applicationId: variables.applicationId }).catch(() => undefined); } } });
  const applicationQuery = trpc.proofloan.getApplication.useQuery({ applicationId: applicationId ?? "_none_" }, { enabled: Boolean(applicationId) && !pollingPaused, retry: (_failureCount, _error) => shouldRetryCreditFileQuery({ isOnline, pollingPaused, failureCount: _failureCount }), refetchInterval: shouldPollCreditFile({ hasApplication: Boolean(applicationId), isOnline, pollingPaused }) ? 5000 : false });
  const app = applicationQuery.data;
  useEffect(() => {
    if (applicationQuery.error) setPollingPaused(true);
  }, [applicationQuery.error]);
  useEffect(() => {
    if (shouldClearMissingApplication({ hasApplicationId: Boolean(applicationId), hasData: applicationQuery.data !== undefined, isLoading: applicationQuery.isLoading, isFetching: applicationQuery.isFetching, hasError: Boolean(applicationQuery.error) }) && applicationQuery.data === null) {
      setApplicationId(null);
      setPollingPaused(false);
      setProofSubmitted(false);
    }
  }, [applicationId, applicationQuery.data, applicationQuery.error, applicationQuery.isFetching, applicationQuery.isLoading]);
  const actionAvailability = getMobileActionAvailability({ isOnline, proofPending: createApplication.isPending, refreshPending: applicationQuery.isFetching, acceptPending: acceptOffer.isPending });
  const creditFileViewState = getMobileCreditFileViewState({ hasApplication: Boolean(app), isLoading: applicationQuery.isLoading, hasError: Boolean(debugDashboardFailure || applicationQuery.error) });
  const currentIndex = useMemo(() => PROOFLOAN_STATES.indexOf(app?.state ?? "Intake"), [app?.state]);

  const startProof = () => {
    if (!shouldInvokeMobileAction({ action: "proof", isOnline, pending: createApplication.isPending, hasApplication: Boolean(applicationId) })) return;
    const validationError = getProofIdentityValidationError(walletAddress, sourceChain);
    if (validationError) {
      setInputError(validationError);
      return;
    }
    setInputError(null);
    proofRequestIdempotencyRef.current = getProofRequestIdempotencyKey(proofRequestIdempotencyRef.current, walletAddress, sourceChain);
    createApplication.mutate({ walletAddress: walletAddress.trim(), sourceChain, idempotencyKey: proofRequestIdempotencyRef.current.key });
  };
  const copyId = async () => {
    if (!app) return;
    setCopyError(null);
    try {
      if (!navigator.clipboard?.writeText) throw new Error("Clipboard access is unavailable on this device.");
      await navigator.clipboard.writeText(app.applicationId);
      setCopied(true);
      copyResetTimer.current = scheduleFeedbackReset(setTimeout, clearTimeout, copyResetTimer.current, () => {
        setCopied(false);
        copyResetTimer.current = null;
      }, 1200);
    } catch (error) {
      setCopied(false);
      setCopyError(error instanceof Error ? error.message : "Clipboard access was unavailable.");
    }
  };
  const refreshCreditFile = () => {
    if (!applicationId || !shouldInvokeMobileAction({ action: "refresh", isOnline, pending: applicationQuery.isFetching, hasApplication: Boolean(applicationId) })) return;
    setDebugDashboardFailure(false);
    setPollingPaused(false);
    void applicationQuery.refetch().catch(() => undefined);
  };
  const submitOffer = () => {
    if (!app || !shouldInvokeMobileAction({ action: "accept", isOnline, pending: acceptOffer.isPending, hasApplication: Boolean(app) })) return;
    acceptanceIdempotencyRef.current = getAcceptanceIdempotencyRef(acceptanceIdempotencyRef.current, app.applicationId);
    acceptOffer.mutate({ applicationId: app.applicationId, idempotencyKey: acceptanceIdempotencyRef.current.key });
  };

  return (
    <div className="min-h-screen overflow-x-clip bg-[#070b12] text-slate-100 selection:bg-cyan-300 selection:text-slate-950">
      <header className="sticky top-0 z-20 border-b border-white/10 bg-[#070b12]/90 backdrop-blur-xl">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-3 sm:px-6 sm:py-4">
          <a href="#top" onClick={() => setActiveSection("top")} className="flex min-w-0 items-center gap-2 sm:gap-3"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-xl sm:h-9 sm:w-9 bg-cyan-300 text-slate-950 shadow-[0_0_28px_rgba(103,232,249,.25)]"><ShieldCheck size={20} /></div><div><div className="truncate font-black tracking-tight">ProofLoan</div><div className="hidden text-[10px] uppercase tracking-[0.24em] text-slate-500 sm:block">Creditcoin underwriting</div></div></a>
          <nav className="hidden items-center gap-7 text-sm text-slate-400 md:flex"><a href="#how-it-works" className="transition hover:text-white">How it works</a><a href="#evidence" className="transition hover:text-white">Evidence</a><a href="#docs" className="transition hover:text-white">Docs</a></nav>
          <Button aria-label="Start a loan" onClick={() => { setActiveSection("apply"); document.getElementById("apply")?.scrollIntoView({ behavior: "smooth" }); }} className="h-11 shrink-0 rounded-full bg-cyan-300 px-3 text-xs font-bold text-slate-950 hover:bg-cyan-200 sm:px-5 sm:text-sm"><span className="sm:hidden">Start</span><span className="hidden sm:inline">Start a loan</span> <ArrowRight size={16} /></Button>
          </div><nav aria-label="Mobile section navigation" className="mobile-section-nav mx-auto flex max-w-7xl gap-2 overflow-x-auto px-4 pb-3 text-[11px] text-slate-400 sm:px-6 md:hidden"><a aria-current={activeSection === "how" ? "page" : undefined} onClick={() => setActiveSection("how")} href="#how-it-works" className={`shrink-0 rounded-full border px-3 py-2 transition ${activeSection === "how" ? "border-cyan-300/50 bg-cyan-300/10 text-cyan-200" : "border-white/10 hover:border-cyan-300/40 hover:text-cyan-200"}`}>How it works</a><a aria-current={activeSection === "evidence" ? "page" : undefined} onClick={() => setActiveSection("evidence")} href="#evidence" className={`shrink-0 rounded-full border px-3 py-2 transition ${activeSection === "evidence" ? "border-cyan-300/50 bg-cyan-300/10 text-cyan-200" : "border-white/10 hover:border-cyan-300/40 hover:text-cyan-200"}`}>Evidence</a><a aria-current={activeSection === "docs" ? "page" : undefined} onClick={() => setActiveSection("docs")} href="#docs" className={`shrink-0 rounded-full border px-3 py-2 transition ${activeSection === "docs" ? "border-cyan-300/50 bg-cyan-300/10 text-cyan-200" : "border-white/10 hover:border-cyan-300/40 hover:text-cyan-200"}`}>Docs</a></nav>
      </header>

      <main id="top" className="mx-auto max-w-7xl overflow-x-clip px-4 sm:px-6">
        {!isOnline && <div role="status" aria-live="assertive" className="mt-4 rounded-xl border border-amber-300/25 bg-amber-300/10 p-3 text-xs leading-5 text-amber-100"><div className="font-semibold">You are offline</div><p className="mt-1 text-amber-100/75">Proof requests and credit-file refreshes are paused until the connection returns. Your current form and displayed evidence remain available.</p></div>}
        {authQuery.data?.role === "admin" && (
          <section aria-label="Replay protection health" className="mt-4 rounded-2xl border border-cyan-300/15 bg-cyan-300/[0.04] p-4 sm:p-5">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <div className="text-[10px] font-semibold uppercase tracking-[0.2em] text-cyan-200/80">Operator health</div>
                <h2 className="mt-1 text-lg font-bold text-white">Replay protection</h2>
                <p className="mt-1 text-xs leading-5 text-slate-400">Read-only counts; identifiers and payloads stay hidden.</p><fieldset aria-describedby="replay-severity-guidance replay-severity-status" className="mt-3 flex flex-wrap items-center gap-2 text-[10px] text-slate-500"><legend className="sr-only">Category severity thresholds. Use the arrow keys to adjust each numeric threshold.</legend><span title="Severity is derived from the bounded recent-event window">Category severity</span><label className="flex items-center gap-1">Attention <input aria-label="Attention threshold" aria-describedby="replay-severity-guidance replay-severity-status" type="number" min={1} max={2} value={replayRefreshSeverityThresholds.attentionCount} onChange={event => { const next = normalizeReplayRefreshSeverityThresholds({ ...replayRefreshSeverityThresholds, attentionCount: Number(event.target.value) }); if (areReplayRefreshSeverityThresholdsEqual(replayRefreshSeverityThresholds, next)) return; setReplayRefreshSeverityThresholds(next); recordReplayThresholdAudit("saved", next); setReplayRefreshSeverityNotice(getReplayRefreshSeverityNotice("saved")); }} className="h-7 w-12 rounded border border-white/10 bg-white/[0.04] px-1 text-center text-slate-200" /></label><label className="flex items-center gap-1">Critical <input aria-label="Critical threshold" aria-describedby="replay-severity-guidance replay-severity-status" type="number" min={2} max={3} value={replayRefreshSeverityThresholds.criticalCount} onChange={event => { const next = normalizeReplayRefreshSeverityThresholds({ ...replayRefreshSeverityThresholds, criticalCount: Number(event.target.value) }); if (areReplayRefreshSeverityThresholdsEqual(replayRefreshSeverityThresholds, next)) return; setReplayRefreshSeverityThresholds(next); recordReplayThresholdAudit("saved", next); setReplayRefreshSeverityNotice(getReplayRefreshSeverityNotice("saved")); }} className="h-7 w-12 rounded border border-white/10 bg-white/[0.04] px-1 text-center text-slate-200" /></label><span id="replay-severity-guidance" className="w-full text-[10px] text-slate-500 sm:w-auto">{getReplayRefreshSeverityExplanation(replayRefreshSeverityThresholds)}</span><span id="replay-severity-status" role="status" aria-live="polite" className="sr-only">{getReplayRefreshSeverityStatusSummary(replayRefreshSeverityThresholds)}{replayRefreshSeverityNotice ? ` ${replayRefreshSeverityNotice}.` : ""}{replayRefreshSeverityPersistenceWarning ? ` ${replayRefreshSeverityPersistenceWarning}` : ""}{replayRefreshSeverityPersistenceStatus ? ` ${replayRefreshSeverityPersistenceStatus}` : ""}</span><button type="button" aria-label="Restore default severity thresholds" onClick={() => { const next = normalizeReplayRefreshSeverityThresholds(); if (areReplayRefreshSeverityThresholdsEqual(replayRefreshSeverityThresholds, next)) return; setReplayRefreshSeverityThresholds(next); recordReplayThresholdAudit("restored", next); setReplayRefreshSeverityNotice(getReplayRefreshSeverityNotice("restored")); }} className="font-semibold text-cyan-200 underline decoration-cyan-200/40 underline-offset-2 hover:text-cyan-100">Restore defaults</button>{replayRefreshSeverityNotice && <span role="status" className="text-cyan-200">{replayRefreshSeverityNotice}</span>}{replayRefreshSeverityPersistenceWarning ? <span role="status" className="w-full text-amber-200 sm:w-auto">{replayRefreshSeverityPersistenceWarning}</span> : replayRefreshSeverityPersistenceStatus && <span role="status" className="w-full text-slate-500 sm:w-auto">{replayRefreshSeverityPersistenceStatus}</span>}</fieldset>
              </div>
              <div className="flex items-start gap-3">
                {safeReplayDiagnostics && <div className="text-right text-[11px] text-slate-500">Updated {formatReplayDiagnosticsTimestamp(safeReplayDiagnostics.generatedAt)}<div className={replayDiagnosticsFreshness === "fresh" ? "text-emerald-300" : "text-amber-200"}>{replayDiagnosticsFreshness === "fresh" ? "Current" : replayDiagnosticsFreshness === "future" ? "Clock skew detected" : "Refresh required"}</div></div>}
                <Button type="button" variant="outline" aria-label={replayDiagnosticsRefresh.label} disabled={!replayDiagnosticsRefresh.enabled} onClick={refreshReplayDiagnostics} className="min-h-9 rounded-lg border-white/15 px-3 text-xs text-slate-200 hover:bg-white/5 disabled:opacity-60"><RefreshCw size={13} className={replayDiagnostics.isFetching ? "animate-spin" : undefined} /> {replayDiagnosticsRefresh.label}</Button>
              </div>
            </div>
            {replayRefreshFeedback.label && replayRefreshOutcome !== "refreshing" && <p role={replayRefreshOutcome === "error" ? "alert" : "status"} className={`mt-4 text-xs ${replayRefreshFeedback.tone === "negative" ? "text-rose-200" : replayRefreshFeedback.tone === "positive" ? "text-emerald-200" : "text-slate-400"}`}>{replayRefreshFeedback.label}</p>}
            {replayDiagnostics.isLoading && <p className="mt-4 text-xs text-slate-400">Loading protected diagnostics…</p>}
            {replayRefreshOutcome === "refreshing" && <p role="status" className="mt-4 text-xs text-slate-400">Refreshing protected diagnostics… Last trustworthy snapshot remains visible.</p>}
            {replayDiagnostics.error && <p role="alert" className="mt-4 text-xs text-rose-200">Replay diagnostics are temporarily unavailable.</p>}
            {replayDiagnostics.data && !safeReplayDiagnostics && <p role="alert" className="mt-4 text-xs text-amber-100">Replay diagnostics returned an invalid payload and are being withheld.</p>}
            {safeReplayDiagnostics && <div className="mt-4 grid gap-3 sm:grid-cols-2">{getReplayDiagnosticsRows(safeReplayDiagnostics, replayDiagnosticsFreshness).map(row => <div key={row.label} className="rounded-xl border border-white/10 bg-[#0d1622] p-3"><div className="flex items-center justify-between gap-3"><span className="text-xs font-semibold text-slate-200">{row.label}</span><span className={`text-[10px] font-semibold uppercase tracking-[0.14em] ${row.tone === "attention" ? "text-amber-200" : "text-emerald-300"}`}>{row.tone === "attention" ? "Attention" : "Clear"}</span></div><div className="mt-3 flex items-end justify-between"><div><div className="text-2xl font-black text-white">{row.pending}</div><div className="text-[10px] uppercase tracking-[0.16em] text-slate-500">Pending</div></div><div className="text-right"><div className="text-lg font-bold text-cyan-200">{row.stale}</div><div className="text-[10px] uppercase tracking-[0.16em] text-slate-500">Stale</div></div></div></div>)}</div>}
            {(replayRefreshTimeline.length > 0 || replayRefreshThresholdAudit.length > 0) && (
              <div className="mt-5 border-t border-white/10 pt-4">
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <div>
                    <div className="flex flex-wrap items-center gap-2"><h3 className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-300">Recent refresh attempts</h3>{replayTimelineFilter !== "all" && <span className="rounded-full border border-cyan-300/20 bg-cyan-300/5 px-2 py-0.5 text-[10px] font-medium text-cyan-200" aria-label={`Active timeline filter: ${getReplayRefreshFilterScopeLabel(replayTimelineFilter, filteredReplayRefreshTimeline.length)}`}>Viewing {getReplayRefreshFilterScopeLabel(replayTimelineFilter, filteredReplayRefreshTimeline.length)}</span>}</div>
                    <span className="text-[10px] text-slate-500">Last six · no identifiers</span>{replayTimelineFilterChangeNotice && <span role="status" className="mt-1 block text-[10px] text-cyan-200">{replayTimelineFilterChangeNotice}</span>}{getReplayRefreshFilterRestorationNotice(replayTimelineFilter, replayTimelineFilterRestored) && <span role="status" className="mt-1 block text-[10px] text-cyan-200">{getReplayRefreshFilterRestorationNotice(replayTimelineFilter, replayTimelineFilterRestored)}</span>}{replayTimelineFilter !== "all" && <button type="button" onClick={() => changeReplayTimelineFilter("all")} className="mt-2 block text-[10px] font-semibold text-cyan-200 underline decoration-cyan-200/40 underline-offset-2 hover:text-cyan-100">Reset filter</button>}
                  </div>
                  <div className="flex flex-wrap rounded-full border border-white/10 p-0.5" role="group" aria-label="Filter refresh attempts">{(["all", "failures", "unavailable", "malformed", "request_error"] as const).map(filter => <button key={filter} type="button" aria-pressed={replayTimelineFilter === filter} onClick={() => changeReplayTimelineFilter(filter)} className={`rounded-full px-2 py-1 text-[10px] font-semibold ${replayTimelineFilter === filter ? "bg-white/10 text-white" : "text-slate-500"}`}>{filter === "all" ? "All" : filter === "failures" ? "Failures" : getReplayRefreshFailureLabel(filter)}</button>)}</div>
                  <div className="text-right">
                    <div className={`text-sm font-bold ${replayRefreshTimelineSummary.status === "critical" ? "text-rose-200" : replayRefreshTimelineSummary.status === "watch" ? "text-amber-200" : "text-emerald-300"}`}>{replayRefreshTimelineSummary.failureRatePercent}% failed</div>
                    <div className="text-[10px] text-slate-500">{replayRefreshTimelineSummary.failures}/{replayRefreshTimelineSummary.attempts} attempts</div>
                  </div>
                  <div className="text-right">
                    <div className={`text-xs font-semibold ${replayRefreshTrend.direction === "rising" ? "text-rose-200" : replayRefreshTrend.direction === "falling" ? "text-emerald-200" : "text-slate-300"}`}>{replayRefreshTrend.direction === "insufficient" ? "Trend pending" : replayRefreshTrend.direction === "rising" ? "Failure trend rising" : replayRefreshTrend.direction === "falling" ? "Failure trend falling" : "Failure trend flat"}</div>
                    {replayRefreshTrend.direction !== "insufficient" && <div className="text-[10px] text-slate-500">{replayRefreshTrend.priorFailureRatePercent}% → {replayRefreshTrend.recentFailureRatePercent}% · {replayRefreshTrend.confidence} confidence</div>}
                  </div>
                </div>
                <div className="mt-3 flex flex-wrap gap-2">{replayRefreshCategoryCounts.filter(item => item.count > 0).map(item => { const trend = replayRefreshCategoryTrends.find(candidate => candidate.category === item.category); const direction = trend?.direction === "rising" ? "↑" : trend?.direction === "falling" ? "↓" : trend?.direction === "flat" ? "→" : "·"; return <span key={item.category} className="rounded-full border border-white/10 bg-white/[0.03] px-2 py-1 text-[10px] text-slate-400" aria-label={`${item.label}: ${item.count}; trend ${trend?.direction ?? "insufficient"}`}>{item.label}: {item.count} {direction}</span>; })}</div>
                {filteredReplayRefreshTimeline.length === 0 ? <p className="mt-3 rounded-lg border border-dashed border-white/10 px-3 py-3 text-xs text-slate-500" role="status">No matching refresh attempts in the current window. {shouldShowReplayRefreshFilterReset({ filter: replayTimelineFilter, visibleCount: filteredReplayRefreshTimeline.length }) && <button type="button" onClick={() => changeReplayTimelineFilter("all")} className="ml-1 font-semibold text-cyan-200 underline decoration-cyan-200/40 underline-offset-2 hover:text-cyan-100">View all attempts</button>}</p> : <ol aria-label="Recent replay diagnostics refresh attempts" className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{[...filteredReplayRefreshTimeline].reverse().map(event => <li key={event.id} className="flex items-center gap-2 rounded-lg border border-white/10 bg-[#0d1622] px-3 py-2"><span className={`h-2 w-2 shrink-0 rounded-full ${event.outcome === "success" ? "bg-emerald-300" : "bg-rose-300"}`} /><span className="min-w-0 text-xs text-slate-300">{event.outcome === "success" ? "Refresh completed" : getReplayRefreshFailureLabel(event.category)}</span><time className="ml-auto shrink-0 text-[10px] text-slate-500">{formatReplayDiagnosticsTimestamp(event.occurredAt)}</time></li>)}</ol>}
                {replayRefreshThresholdAudit.length > 0 && <div className="mt-4 border-t border-white/10 pt-3"><div className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-400">Recent operator changes</div><ol aria-label="Recent replay severity threshold changes" className="mt-2 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{[...replayRefreshThresholdAudit].reverse().map(event => <li key={event.id} aria-label={getReplayRefreshThresholdAuditAriaLabel(event)} className="rounded-lg border border-cyan-300/10 bg-cyan-300/[0.03] px-3 py-2"><div className="text-xs text-slate-300">{getReplayRefreshThresholdAuditLabel(event)}</div><div className="mt-1 text-[10px] text-slate-500">Attention {event.attentionCount} · Critical {event.criticalCount}<time className="ml-2">{formatReplayDiagnosticsTimestamp(event.occurredAt)}</time></div></li>)}</ol><p className="mt-2 text-[10px] text-slate-600">Bounded session view; no identities, payloads, or raw diagnostics are recorded.</p></div>}
              </div>
            )}
          </section>
        )}
        <section className="grid gap-10 py-14 sm:gap-12 sm:py-20 lg:grid-cols-[1.05fr_.95fr] lg:items-center lg:py-28">
          <div><Badge className="mb-6 border border-cyan-300/30 bg-cyan-300/10 text-cyan-200">ATTESTCOIN PROTOCOL × CREDITCOIN</Badge><h1 className="max-w-3xl text-[2.75rem] font-black leading-[.98] tracking-[-.055em] text-white sm:text-7xl">Credit that starts with <span className="text-cyan-300">proof.</span></h1><p className="mt-6 max-w-2xl text-base leading-7 text-slate-400 sm:mt-7 sm:text-lg sm:leading-8">ProofLoan turns verified cross-chain behavior into a bounded credit decision. Every fact, model output, policy check, and Creditcoin execution is visible in one auditable trail.</p><div className="mt-8 flex flex-col gap-3 sm:mt-9 sm:flex-row sm:flex-wrap sm:gap-4"><Button onClick={() => { setActiveSection("apply"); document.getElementById("apply")?.scrollIntoView({ behavior: "smooth" }); }} className="h-12 w-full rounded-full bg-cyan-300 px-6 font-bold text-slate-950 hover:bg-cyan-200 sm:w-auto">Prove my history <ArrowRight size={18} /></Button><a href="#how-it-works" className="inline-flex h-12 w-full items-center justify-center gap-2 rounded-full border border-white/15 px-6 font-semibold text-slate-200 transition hover:border-cyan-300/50 hover:bg-white/5 sm:w-auto">See the trust boundary</a></div><div className="mt-8 flex flex-wrap gap-x-4 gap-y-3 text-xs text-slate-500 sm:mt-10 sm:gap-5"><span className="flex items-center gap-2"><LockKeyhole size={14} className="text-cyan-300" /> No opaque oracle</span><span className="flex items-center gap-2"><FileCheck2 size={14} className="text-cyan-300" /> Typed evidence</span><span className="flex items-center gap-2"><Sparkles size={14} className="text-cyan-300" /> AI advisory, not signer</span></div></div>
          <div className="mobile-trace relative overflow-hidden rounded-[1.5rem] border border-white/10 bg-[#0b121d] p-3 sm:rounded-[2rem] sm:p-5 shadow-2xl shadow-cyan-950/20"><div className="absolute -right-20 -top-20 h-64 w-64 rounded-full bg-cyan-300/10 blur-3xl" /><div className="relative rounded-2xl border border-white/10 bg-[#0d1622] p-4 sm:rounded-3xl sm:p-6"><div className="flex items-center justify-between"><span className="max-w-[10rem] text-[10px] uppercase tracking-[.18em] text-slate-500 sm:max-w-none sm:text-xs sm:tracking-[.22em]">Live underwriting trace</span><span className="flex items-center gap-2 text-xs text-emerald-300"><span className="h-2 w-2 rounded-full bg-emerald-300" /> Testnet ready</span></div><div className="mt-8 space-y-4"><TraceRow label="Source transaction" value="Ethereum Sepolia" done /><TraceRow label="Attestcoin proof" value="VerifiedFact · 3 records" done /><TraceRow label="AI decision" value="Risk tier B · 92% confidence" done /><TraceRow label="RiskGuard" value="Offer within bounds" done /></div><div className="mt-8 rounded-2xl border border-cyan-300/20 bg-cyan-300/5 p-4"><div className="text-xs text-slate-500">Indicative offer</div><div className="mt-1 flex items-baseline justify-between"><span className="text-3xl font-black text-white sm:text-4xl">1,500 <small className="text-base text-slate-400">USDC</small></span><span className="text-right text-sm font-semibold text-cyan-200">11.5% APR<br /><span className="text-xs font-normal text-slate-500">90 day term</span></span></div></div></div></div>
        </section>

        <section id="how-it-works" className="scroll-mt-24 border-t border-white/10 py-16"><div className="mb-9 max-w-2xl"><p className="text-xs font-bold uppercase tracking-[.24em] text-cyan-300">One bounded loop</p><h2 className="mt-3 text-3xl font-black tracking-tight text-white sm:text-4xl">Evidence → inference → policy → execution.</h2></div><div className="grid gap-4 md:grid-cols-4">{[["01", "Prove", "The Attestcoin proof worker returns verified, typed facts from a source chain."], ["02", "Score", "A server-side model builds a FeatureVector and produces calibrated PD plus reasons."], ["03", "Guard", "RiskGuard deterministically checks amount, LTV, rate, freshness, confidence, and liquidity."], ["04", "Execute", "Only an accepted, bounded offer crosses the Creditcoin testnet execution boundary."]].map(([n, title, body]) => <div key={n} className="rounded-3xl border border-white/10 bg-white/[.03] p-5"><div className="text-xs font-bold text-cyan-300">{n}</div><h3 className="mt-8 text-xl font-bold text-white">{title}</h3><p className="mt-3 text-sm leading-6 text-slate-400">{body}</p></div>)}</div></section>

        <section id="apply" className="scroll-mt-24 grid gap-6 py-12 lg:grid-cols-[.88fr_1.12fr]"><Card className="min-w-0 border-white/10 bg-[#0b121d] text-white"><CardHeader><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.22em] text-cyan-300">Borrower intake</p><CardTitle className="mt-2 text-xl sm:text-2xl">Start your proof request</CardTitle></div><WalletCards className="text-cyan-300" /></div></CardHeader><CardContent className="space-y-5"><label className="block text-xs font-medium text-slate-300 sm:text-sm">Preview wallet identifier or source tx hash<input aria-label="Preview wallet identifier or source transaction hash" inputMode="text" autoCapitalize="none" autoCorrect="off" spellCheck={false} placeholder="Paste a mined 32-byte source transaction hash" value={walletAddress} onChange={e => setWalletAddress(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-white/10 bg-black/20 px-4 font-mono text-[13px] text-white sm:text-sm outline-none ring-cyan-300/40 focus:ring-2" /></label><label className="block text-xs font-medium text-slate-300 sm:text-sm">Source chain<select aria-label="Source chain" value={sourceChain} onChange={e => setSourceChain(e.target.value as SourceChain)} className="mt-2 h-12 w-full rounded-xl border border-white/10 bg-[#111a28] px-4 text-sm text-white outline-none ring-cyan-300/40 focus:ring-2"><option>Ethereum Sepolia</option><option>Polygon Amoy</option></select></label><Button aria-busy={createApplication.isPending} disabled={!actionAvailability.canSubmitProof} onClick={startProof} className="h-12 w-full rounded-xl bg-cyan-300 font-bold text-slate-950 hover:bg-cyan-200">{createApplication.isPending ? <><Loader2 className="animate-spin" size={17} /> <span>Verifying with Attestcoin…</span></> : <><span>Fetch and verify history</span> <ArrowRight size={17} /></>}</Button>{inputError && <MobileErrorNotice title="Input needs attention" error={{ message: `[PROOFLOAN_VALIDATION_ERROR] ${inputError}` }} />}<p className="text-xs leading-5 text-slate-500">Paste a mined 32-byte source transaction hash to run the official @gluwa/usc-sdk ProofBuilder + Creditcoin BlockProver path. A short preview identifier uses the labeled preview adapter; an address-shaped value must be a valid EVM identity for the selected chain. Raw RPC data is never treated as financial truth.</p>{proofSubmitted && <p role="status" aria-live="polite" className="rounded-xl border border-emerald-300/20 bg-emerald-400/10 p-3 text-xs leading-5 text-emerald-200">Proof request accepted. Your evidence graph is ready below.</p>}{createApplication.error && <MobileErrorNotice title="Proof request failed" error={createApplication.error} onRetry={walletAddress.trim().length >= 8 ? startProof : undefined} />}</CardContent></Card>

          <Card role="region" aria-label="ProofLoan borrower dashboard" className="min-w-0 scroll-mt-24 border-white/10 bg-[#0b121d] text-white" id="evidence"><CardHeader><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.22em] text-cyan-300">Borrower dashboard</p><CardTitle className="mt-2 text-xl sm:text-2xl">Your verifiable credit file</CardTitle><p className="mt-1 text-xs text-slate-500 sm:hidden">Evidence, decision, and audit in one trail</p></div>{app && <div className="flex items-center gap-2"><Badge className={app.state === "Rejected" ? "bg-rose-400/10 text-rose-300" : "bg-emerald-400/10 text-emerald-300"}>{app.state}</Badge><Button type="button" variant="outline" aria-busy={applicationQuery.isFetching} aria-label="Refresh credit file" disabled={!actionAvailability.canRefresh} onClick={refreshCreditFile} className="min-h-10 rounded-full border-white/10 px-3 text-[11px] text-slate-300 hover:bg-white/5">{applicationQuery.isFetching ? "Refreshing…" : "Refresh"}</Button></div>}</div></CardHeader><CardContent>{creditFileViewState === "error" ? <MobileErrorNotice title="Unable to refresh the credit file" error={debugDashboardFailure ? { message: "[PROOFLOAN_DATABASE_ERROR] Simulated dashboard refresh failure." } : applicationQuery.error!} onRetry={refreshCreditFile} /> : creditFileViewState === "loading" ? <div role="status" aria-live="polite" className="grid min-h-[270px] place-items-center rounded-2xl border border-dashed border-white/10 px-5 text-center"><div><Loader2 className="mx-auto mb-3 animate-spin text-cyan-300" size={24} /><p className="font-semibold text-slate-300">Loading your credit file</p><p className="mt-2 text-sm leading-6 text-slate-500">Verified evidence and recovery status are being retrieved.</p></div></div> : !app ? <div className="grid min-h-[270px] place-items-center rounded-2xl border border-dashed border-white/10 text-center"><div><CircleDot className="mx-auto mb-3 text-slate-600" /><p className="font-semibold text-slate-300">No application in progress</p><p className="mt-2 text-sm leading-6 text-slate-500">Submit a wallet proof request to populate your evidence graph.</p><button onClick={() => document.getElementById("apply")?.scrollIntoView({ behavior: "smooth" })} className="mt-4 inline-flex min-h-11 items-center justify-center gap-2 rounded-full border border-cyan-300/30 px-4 text-xs font-semibold text-cyan-200 hover:bg-cyan-300/10">Start a proof request <ArrowRight size={14} /></button></div></div> : <div className="space-y-5 sm:space-y-6"><div role="status" aria-live="polite" className="rounded-xl border border-cyan-300/15 bg-cyan-300/5 px-3 py-2 text-xs leading-5 text-cyan-200 sm:hidden">Current underwriting step: <span className="font-semibold">{app.state}</span></div><div aria-label="Mobile credit file context" className="mobile-dashboard-context sm:hidden"><span className="font-semibold text-slate-200">{activeTab === "evidence" ? "VerifiedFact" : activeTab === "decision" ? "Decision" : "Audit"}</span><span className="text-slate-600">·</span><span>{app.sourceChain}</span><span className="ml-auto text-cyan-200">{app.state}</span></div><div aria-label="ProofLoan state tracker" className="mobile-state-tracker -mx-1 flex snap-x items-center gap-3 overflow-x-auto px-1 pb-3">{PROOFLOAN_STATES.map((state, i) => <div key={state} aria-current={i === currentIndex ? "step" : undefined} className={`flex shrink-0 items-center gap-2 text-[11px] ${i <= currentIndex ? "text-cyan-200" : "text-slate-600"}`}><span className={`grid h-8 w-8 place-items-center rounded-full border text-xs ${i < currentIndex ? "border-cyan-300 bg-cyan-300 text-slate-950" : i === currentIndex ? "border-cyan-300 bg-cyan-300/10 text-cyan-200" : "border-white/10"}`}>{i < currentIndex ? <Check size={13} /> : i + 1}</span><span className="font-medium sm:hidden">{state === "EvidencePending" ? "Evidence" : state === "OfferPrepared" ? "Offer" : state === "AwaitingAcceptance" ? "Accept" : state}</span><span className="hidden sm:inline">{state}</span>{i < PROOFLOAN_STATES.length - 1 && <span className="mx-1 h-px w-5 bg-white/10" />}</div>)}</div><Tabs value={activeTab} onValueChange={setActiveTab}><p id="credit-file-swipe-hint" className="mb-2 text-[11px] text-slate-500 sm:hidden">Swipe to view evidence, decision, and audit trail</p><p className="mb-3 text-xs font-medium text-cyan-200 sm:hidden">Viewing: {activeTab === "evidence" ? "VerifiedFact evidence" : activeTab === "decision" ? "underwriting decision" : "audit trail"}</p><TabsList aria-label="Credit file views" aria-describedby="credit-file-swipe-hint" className="mobile-dashboard-tabs w-full touch-pan-x justify-start overflow-x-auto bg-white/5 p-1 sm:w-auto"><TabsTrigger className="min-w-max" value="evidence">VerifiedFact</TabsTrigger><TabsTrigger className="min-w-max" value="decision">Decision</TabsTrigger><TabsTrigger className="min-w-max" value="audit">Audit trail</TabsTrigger></TabsList><TabsContent value="evidence" aria-label="VerifiedFact evidence records" className="mt-4 space-y-3 sm:mt-5">{app.facts.map(fact => <article key={fact.id} aria-label={`${fact.eventType} verified fact`} className="mobile-fact-card rounded-2xl border border-white/10 bg-black/15 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex min-w-0 items-center gap-2"><Badge className="bg-emerald-400/10 text-emerald-300">{fact.eventType}</Badge><span className="truncate font-semibold text-white">{fact.amount}</span></div><span className="shrink-0 rounded-full bg-emerald-400/10 px-2 py-1 text-[10px] text-emerald-300">{fact.freshness}</span></div><div aria-label="VerifiedFact metadata" className="mobile-fact-metadata mt-3 grid gap-3 text-xs text-slate-400 sm:grid-cols-2"><div className="sm:col-span-2"><span className="text-[10px] uppercase tracking-[.16em] text-slate-600">Verified provenance</span></div><div>Chain <b className="ml-2 font-medium text-slate-200">{fact.chain}</b></div><div>Source block <b className="ml-2 font-medium text-slate-200">{fact.sourceBlock.toLocaleString()}</b></div><div className="min-w-0">Tx hash <b title={fact.txHash} className="ml-2 block break-all font-mono font-medium text-slate-200 sm:inline">{fact.txHash}</b></div><div>USC verification block <b className="ml-2 font-medium text-slate-200">{fact.verificationBlock.toLocaleString()}</b></div></div><div className="mt-3 flex flex-wrap items-start gap-2 border-t border-white/10 pt-3 text-[11px] leading-5 text-slate-500"><FileCheck2 size={13} className="text-cyan-300" /> {fact.proofWorker} · root {fact.proofRoot}</div></article>)}</TabsContent><TabsContent value="decision" aria-label="Underwriting decision and offer" className="mt-4 sm:mt-5">{app.decision && app.offer ? <div className="space-y-4"><div aria-label="Decision summary metrics" className="mobile-decision-metrics grid min-w-0 gap-2 sm:grid-cols-3"><div className="mobile-summary-kicker col-span-full text-[10px] font-bold uppercase tracking-[.18em] text-cyan-300 sm:hidden">Decision snapshot</div><div className="min-w-0"><Metric label="30d PD" value={`${(app.decision.pd30 * 100).toFixed(1)}%`} /></div><div className="min-w-0"><Metric label="Confidence" value={`${(app.decision.confidence * 100).toFixed(0)}%`} /></div><div className="min-w-0"><Metric label="Risk tier" value={app.decision.riskTier} /></div></div><div className="mobile-offer-panel rounded-2xl border border-cyan-300/20 bg-cyan-300/5 p-4"><div className="mobile-offer-status" role="status"><span className="h-1.5 w-1.5 rounded-full bg-cyan-300" /> {app.offer.status === "Ready" ? "Offer ready" : app.offer.status}</div><div className="mb-3 flex items-center justify-between"><div><div className="text-xs font-bold uppercase tracking-[.18em] text-cyan-200">RiskGuard offer</div><div className="mt-1 text-3xl font-black text-white">{app.offer.amount.toLocaleString()} USDC</div><div className="mt-1 text-xs text-slate-500">Bounded by policy, liquidity, and freshness</div></div><div className="text-right text-sm text-cyan-200">{app.offer.apr}% APR<br /><span className="text-xs text-slate-500">{app.offer.termDays} days · {(app.offer.ltv * 100).toFixed(0)}% LTV</span></div></div>{app.offer.status === "Ready" && <Button aria-busy={acceptOffer.isPending} disabled={!actionAvailability.canAccept} onClick={submitOffer} className="mobile-acceptance-cta mt-5 h-12 w-full rounded-xl bg-cyan-300 px-3 text-center text-xs font-bold text-slate-950 hover:bg-cyan-200 sm:text-sm">{acceptOffer.isPending ? <><Loader2 className="animate-spin" size={16} /> <span>Submitting on Creditcoin…</span></> : <><span>Accept and submit on Creditcoin</span> <ArrowRight size={16} /></>}</Button>}{app.state === "Executed" && <div className="mt-4 space-y-2"><div className="flex items-center gap-2 rounded-xl bg-emerald-400/10 p-3 text-sm text-emerald-300"><Check size={16} /> Creditcoin testnet execution recorded.</div>{!isLiveTxHash(app.walletAddress) && <Button variant="outline" disabled={!actionAvailability.canAccept} aria-busy={acceptOffer.isPending} onClick={submitOffer} className="h-10 w-full rounded-xl border-rose-300/20 text-xs text-rose-200 hover:bg-rose-400/10">Test replay guard (preview)</Button>}</div>}{offerSubmitted && <p role="status" aria-live="polite" className="mt-4 rounded-xl border border-emerald-300/20 bg-emerald-400/10 p-3 text-xs leading-5 text-emerald-200">Acceptance submitted. Creditcoin execution is being confirmed.</p>}{shouldShowAcceptanceError({ state: app.state, hasError: Boolean(acceptOffer.error) }) && <MobileErrorNotice title="Acceptance failed" error={acceptOffer.error!} onRetry={app.state === "AwaitingAcceptance" ? submitOffer : undefined} />}</div><div aria-label="AI reason codes" className="mobile-reason-codes rounded-xl border border-white/10 bg-black/10 p-3"><div className="mb-2 flex items-center justify-between gap-2"><div className="text-[10px] uppercase tracking-[.16em] text-slate-600">Reason codes</div><span className="text-[10px] text-slate-600">AI advisory</span></div><div className="flex flex-wrap gap-2">{app.decision.reasonCodes.map(reason => <Badge key={reason} className="border border-white/10 bg-white/5 text-slate-300">{reason}</Badge>)}</div></div></div> : <p className="text-sm text-slate-500">Decision is being assembled from verified evidence.</p>}</TabsContent><TabsContent value="audit" aria-label="Hash-linked audit trail" className="mt-4 space-y-3 sm:mt-5">{app.audit.map(event => <div key={event.hash} className="flex gap-3 rounded-xl border border-white/10 bg-black/10 p-3"><div className="mt-1 h-2 w-2 shrink-0 rounded-full bg-cyan-300" /><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="font-semibold text-white">{event.label}</span><span className="rounded-full bg-white/[.03] px-2 py-1 text-[10px] text-slate-600">{new Date(event.timestamp).toLocaleTimeString()}</span></div><p className="mt-1 break-words text-sm leading-6 text-slate-400">{event.detail}</p><code title={event.hash} className="mt-2 block break-all text-[10px] leading-4 text-slate-600">event hash {event.hash}</code></div></div>)}{app && <button aria-label="Copy application ID" onClick={copyId} className="mobile-copy-action mt-2 inline-flex min-h-11 items-center gap-2 rounded-full border border-cyan-300/20 px-3 text-xs text-cyan-300 hover:bg-cyan-300/10 hover:text-cyan-200">{copied ? <Check size={13} /> : <Copy size={13} />} {copied ? "Application ID copied" : `${app.applicationId} · copy ID`}</button>}{copyError && <div className="mt-3"><MobileErrorNotice title="Copy unavailable" error={{ message: `[PROOFLOAN_VALIDATION_ERROR] ${copyError}` }} /></div>}</TabsContent></Tabs></div>}</CardContent></Card></section>

        <section id="docs" className="scroll-mt-24 border-t border-white/10 py-16"><div className="grid gap-8 lg:grid-cols-[.8fr_1.2fr]"><div><p className="text-xs font-bold uppercase tracking-[.24em] text-cyan-300">Technical docs</p><h2 className="mt-3 text-3xl font-black tracking-tight text-white">The trust boundary is the product.</h2><p className="mt-4 max-w-xl leading-7 text-slate-400">ProofLoan keeps evidence, inference, policy, and execution separate. The AI can be wrong without gaining authority to move funds; the Attestcoin proof worker can be unavailable without silently turning raw RPC into truth.</p><a href="https://docs.creditcoin.org/attestcoin-protocol/dapp-builder-infrastructure/attestcoin-sdk-usc-sdk.md" target="_blank" rel="noreferrer" className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-cyan-300">Read Attestcoin Protocol USC SDK docs <ExternalLink size={15} /></a></div><div className="rounded-3xl border border-white/10 bg-[#0b121d] p-5"><pre className="overflow-x-auto text-sm leading-7 text-slate-400"><span className="text-cyan-300">SourceTransaction</span>  →  <span className="text-emerald-300">VerifiedFact</span>  →  <span className="text-purple-300">FeatureVector</span>  →  <span className="text-amber-300">Decision</span>  →  <span className="text-pink-300">Offer</span>  →  <span className="text-cyan-300">Creditcoin Loan</span>{"\n\n"}<span className="text-slate-500">USC verifier</span>       evidence authority{"\n"}<span className="text-slate-500">AI model</span>          advisory inference{"\n"}<span className="text-slate-500">RiskGuard</span>         deterministic policy{"\n"}<span className="text-slate-500">LoanPool</span>         bounded execution</pre></div></div></section>
      </main>
      <footer className="border-t border-white/10"><div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 px-6 py-6 text-xs text-slate-500"><span>ProofLoan · built for BUIDL CTC 2026 Fall</span><span>Attestcoin Protocol integration · Creditcoin testnet demo</span></div></footer>
    </div>
  );
}

function TraceRow({ label, value, done }: { label: string; value: string; done?: boolean }) { return <div className="mobile-trace-row flex items-center gap-3"><div className={`grid h-8 w-8 place-items-center rounded-full ${done ? "bg-emerald-400/15 text-emerald-300" : "bg-white/5 text-slate-500"}`}>{done ? <Check size={15} /> : <CircleDot size={15} />}</div><div className="flex-1"><div className="text-sm text-slate-300">{label}</div><div className="text-xs text-slate-500">{value}</div></div></div>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="rounded-2xl border border-white/10 bg-black/15 p-4"><div className="text-xs text-slate-500">{label}</div><div className="mt-1 text-2xl font-black text-white">{value}</div></div>; }
